var t=`1334-rocoto-relleno`;var n=`world-1334`;var o=`PE`;var r=`south-america`;var s=4;var a=84;var l={en:`Rocoto Relleno`,ua:`Рокото рельєно`};var g={en:`Rocoto Relleno is a dish from Peru featuring rocoto pepper, ground beef, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Рокото рельєно, страва кухні країни Перу з такими основними складниками: перець рокото, яловичий фарш, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`rocoto-pepper`,5,`pcs`],[`water`,1e3,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:17,i:[[`ground-beef`,500,`g`],[`yellow-onion`,150,`g`],[`garlic`,4,`clove`],[`raisin`,65,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:11,i:[[`queso-fresco`,180,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 35 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 35 хвилин до готовності.`,t:[`baking`],m:35,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,25,`g`]]}];var u={slug:t,id:n,country:`PE`,region:r,servings:4,minutes:84,title:l,text:g,steps:h};export{o as country,u as default,n as id,a as minutes,r as region,s as servings,t as slug,h as steps,g as text,l as title};